/**
 * Celsius Converter
 * node starter/index.js
 */

const readline = require("node:readline");

function toFahrenheit(celsius) {
let temperature = Number.parseFloat(celsius);
  // TODO: return converted value
  return (temperature * 9/5 + 32);
}

function main() {
  const rl = readline.createInterface({ input: process.stdin });

  rl.on("line", (line) => {
    // TODO: parse, call toFahrenheit, print F: X.X

    if (Number.isFinite(Number.parseFloat(line))){
      console.log("F:", toFahrenheit(line).toFixed(1));
    rl.close();
}
else{
 process.stdout.write("ERROR: invalid temperature");
    rl.close();
}

  });
}

if (require.main === module) {
  main();
}

module.exports = { toFahrenheit };

